def _examples(command_class):
    doc = command_class.__doc__ or ""
    return [
        line.strip()
        for line in doc.splitlines()
        if line.strip().startswith("az agentfabric ")
    ]


class AgentfabricScenario(ScenarioTest):

    def test_agentfabric_command_help(self):
        commands = (
            "agentfabric",
            "agentfabric member",
            "agentfabric aks",
            "agentfabric egress-trust-bundle",
            "agentfabric policy-group",
            *(command for command, _, _ in COMMANDS),
            *HELP_ONLY_COMMANDS,
        )
        for command in commands:
            try:
                self.cmd(f"az {command} --help")
            except SystemExit as ex:
                self.assertEqual(ex.code, 0, f"{command} help failed")

    def test_agentfabric_examples_parse(self):
        for command, module_name, class_name in COMMANDS:
            command_class = getattr(importlib.import_module(module_name), class_name)
            examples = _examples(command_class)
            self.assertTrue(examples, command)
            for example in examples:
                tokens = shlex.split(example)
                self.assertEqual(tokens[:2], ["az", "agentfabric"], example)
                escaped_example = example.replace("{", "{{").replace("}", "}}")
                try:
                    self.cmd(f"{escaped_example} --help")
                except SystemExit as ex:
                    self.assertEqual(ex.code, 0, f"Example failed to parse: {example}")


